export const meanValid=a=>{const v=a.filter(Number.isFinite);return v.length?v.reduce((s,x)=>s+x,0)/v.length:null};
export const monthlyObservation=(a,y,m)=>a.filter(r=>r[0].startsWith(`${y}-${String(m+1).padStart(2,'0')}`)&&Number.isFinite(r[1])).sort((a,b)=>b[0].localeCompare(a[0]))[0]??null;
export function pointInPolygon(p,poly){let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])inside=!inside}return inside}
export function areaHa(p){if(p.length<3)return 0;const lat=meanValid(p.map(a=>a[1])),x=111320*Math.cos(lat*Math.PI/180),y=111320;let sum=0;for(let i=0;i<p.length;i++){const a=p[i],b=p[(i+1)%p.length];sum+=(a[0]-p[0][0])*x*(b[1]-p[0][1])*y-(b[0]-p[0][0])*x*(a[1]-p[0][1])*y}return Math.abs(sum)/20000}
export function validatePolygon(p){if(!Array.isArray(p)||p.length<3)return 'Mark at least three corners.';if(p.length>100)return 'Use no more than 100 corners.';if(p.some(a=>!Array.isArray(a)||a.length!==2||!a.every(Number.isFinite)||Math.abs(a[0])>180||Math.abs(a[1])>80))return 'Coordinates must be valid, between 80°S and 80°N.';if(new Set(p.map(a=>a.join(','))).size!==p.length)return 'Remove duplicate corners.';const xs=p.map(a=>a[0]),ys=p.map(a=>a[1]);if((Math.max(...xs)-Math.min(...xs))*111320*Math.cos(p[0][1]*Math.PI/180)>6000||(Math.max(...ys)-Math.min(...ys))*111320>6000)return 'Select one field, less than 6 km across.';const cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);for(let i=0;i<p.length;i++)for(let j=i+1;j<p.length;j++){if(j===i+1||(i===0&&j===p.length-1))continue;const a=p[i],b=p[(i+1)%p.length],c=p[j],d=p[(j+1)%p.length];if(cross(a,b,c)*cross(a,b,d)<=0&&cross(c,d,a)*cross(c,d,b)<=0)return 'Boundary edges cross. Draw corners in order.'}if(areaHa(p)<.001)return 'The boundary is too small or has no area.';return null}
export function weatherMonth(src,y,m){if(!src)return null;const start=Date.parse(src.start+'T00:00:00Z'),rain=[],temp=[];src.p.T2M.forEach((v,i)=>{const d=new Date(start+i*86400000);if(d.getUTCFullYear()===y&&d.getUTCMonth()===m){rain.push(src.p.PRECTOTCORR?.[i]);temp.push(v)}});const r=rain.filter(Number.isFinite);return {rain:r.length?r.reduce((a,b)=>a+b,0):null,temp:meanValid(temp),days:r.length,expected:new Date(Date.UTC(y,m+1,0)).getUTCDate()}}
